-- Write the full E-commerce Virtual Assistant course.
-- Content remains draft and unpublished until practitioner review.

update public.training_courses
set estimated_minutes = 360,
    content_version = content_version + 1,
    reviewed_by = null,
    last_reviewed_at = null,
    status = 'draft',
    published_at = null,
    updated_at = now()
where slug = 'ecommerce-virtual-assistant';

update public.training_lessons l
set content = '[{"type":"heading","text":"What an e-commerce VA is actually supporting"},{"type":"paragraph","text":"An online store is a chain of connected systems: product data, storefront, checkout, payment, inventory, fulfilment, shipping, customer service, returns, promotions, and reporting. An E-commerce Virtual Assistant creates value by keeping those handoffs accurate and visible. The work is not just ''upload products'' or ''answer emails''. It is operational support across the full order lifecycle."},{"type":"heading","text":"The basic customer journey"},{"type":"steps","items":["A customer discovers a product through search, ads, social, email, a marketplace, or direct traffic.","They review product information, price, availability, shipping, and policy information.","They add products or variants to cart.","They complete checkout and payment.","The order enters fulfilment.","The warehouse, supplier, store team, or third-party provider prepares and ships it.","Tracking and delivery status are communicated.","The customer may ask a question, request a return, report damage, or need an exchange.","The store records the outcome for inventory, support, finance, and reporting."]},{"type":"heading","text":"Understand the systems before changing data"},{"type":"list","items":["Storefront or commerce platform","Inventory or warehouse system","Payment processor","Shipping or fulfilment provider","Customer support platform","CRM or email system","Marketplace accounts","Accounting or finance system","Product-information source","Reporting or analytics tools"]},{"type":"callout","title":"One action may affect several systems","text":"Changing a SKU, product title, price, or inventory setting in one place can affect fulfilment, marketplaces, reporting, customer communication, or accounting. Find the source of truth and understand synchronization before making bulk changes."},{"type":"heading","text":"The VA operating boundary"},{"type":"paragraph","text":"A VA may process approved operational work, but should not silently invent prices, refunds, promotional terms, stock availability, product claims, fraud decisions, tax treatment, or customer promises. Where the store has policies, approval limits, or specialist owners, follow those rules and escalate exceptions."},{"type":"heading","text":"A healthy order lifecycle"},{"type":"list","items":["Product data is accurate before the customer buys.","Inventory status is credible.","Payment and order states are visible.","Exceptions are caught early.","The fulfilment owner receives the right information.","Tracking reaches the customer.","Support can see what happened.","Returns and refunds follow approved policy.","Inventory and reporting reflect the final outcome."]},{"type":"scenario","title":"The order exists but cannot ship","text":"A paid order contains a variant that the storefront showed as available, but the fulfilment system has zero stock. Do not mark it fulfilled or invent a restock date. Confirm the inventory source, flag the mismatch, notify the responsible owner, and use the approved out-of-stock customer process."},{"type":"heading","text":"Common beginner mistakes"},{"type":"list","items":["Editing products directly without checking which system owns the data.","Assuming paid means ready to ship.","Treating every support request as a refund request.","Promising delivery dates that the carrier has not confirmed.","Changing stock counts to make a listing appear available.","Using a marketplace policy from one channel on another without checking.","Deleting failed or cancelled orders because they make reports look messy."]},{"type":"heading","text":"Practice"},{"type":"paragraph","text":"Map a fictional store from product creation to completed delivery. For each stage, name the source system, the person or team that owns the decision, what the VA can do independently, and the exception that should trigger escalation."}]'::jsonb,
    estimated_minutes = 30,
    content_version = l.content_version + 1,
    reviewed_by = null,
    last_reviewed_at = null,
    is_published = false,
    updated_at = now()
from public.training_modules m
join public.training_courses c on c.id = m.course_id
where l.module_id = m.id
  and c.slug = 'ecommerce-virtual-assistant'
  and l.slug = 'how-an-online-store-operates';

update public.training_lessons l
set content = '[{"type":"heading","text":"Product data is operational infrastructure"},{"type":"paragraph","text":"A product record can feed the website, search results, marketplace listings, warehouse picking, purchase orders, customer service, analytics, and accounting. Small data errors multiply quickly, so product administration should start with clear definitions and a reliable source of truth."},{"type":"heading","text":"Know the building blocks"},{"type":"list","items":["Product: the main item or offer.","Variant: a purchasable option such as size, color, material, or pack size.","SKU: the store''s internal stock-keeping identifier.","Barcode or external identifier: a standardized or supplier-provided code where used.","Price: the approved selling amount for a product or variant.","Compare-at or reference price: a separate pricing field that may have legal or policy implications depending on market and platform.","Inventory quantity: stock available according to the source system.","Attribute: structured information such as size, material, compatibility, or dimensions."]},{"type":"heading","text":"SKU discipline"},{"type":"list","items":["Keep SKUs unique under the client''s convention.","Do not recycle retired SKUs unless the client explicitly allows it.","Do not edit a SKU casually if warehouse, marketplace, accounting, or supplier systems depend on it.","Record variant relationships correctly.","Use the approved format consistently."]},{"type":"callout","title":"Never infer product facts from the image","text":"A photo may suggest a color, size, material, compatibility, bundle quantity, or feature, but visual appearance is not a reliable product-data source. Use the approved product sheet, supplier record, or other defined source."},{"type":"heading","text":"Source hierarchy"},{"type":"steps","items":["Use the client''s designated product-information source first.","Check supplier or manufacturer data only where the client has approved that source.","Use current approved pricing data.","Resolve conflicts before copying information to other channels.","Record the source of unusual or frequently disputed fields when helpful."]},{"type":"heading","text":"Variant QA"},{"type":"list","items":["Every option combination is intentional.","Variant names are consistent.","SKUs are unique.","Prices are correct.","Images are attached to the correct variant where required.","Inventory tracking is correct.","Unavailable combinations are not accidentally purchasable.","Weight or shipping data is present if required."]},{"type":"scenario","title":"Two sizes share one SKU","text":"A bulk import creates separate Small and Medium variants with the same SKU. Do not leave it because the storefront renders correctly. Duplicate SKUs can create fulfilment and inventory errors. Stop the affected update, identify the approved SKU mapping, fix the source, and re-check downstream systems."},{"type":"heading","text":"Product-data changes that deserve caution"},{"type":"list","items":["Price","SKU","Barcode","Tax-related settings","Inventory policy","Fulfilment location","Shipping weight","Subscription settings","Marketplace identifiers","Product-status changes such as active, draft, archived"]},{"type":"heading","text":"Practice"},{"type":"paragraph","text":"Create a fictional product with four variants. Define the product title, variant options, SKUs, price, inventory source, weight, image mapping, and five QA checks you would run before publishing it."}]'::jsonb,
    estimated_minutes = 30,
    content_version = l.content_version + 1,
    reviewed_by = null,
    last_reviewed_at = null,
    is_published = false,
    updated_at = now()
from public.training_modules m
join public.training_courses c on c.id = m.course_id
where l.module_id = m.id
  and c.slug = 'ecommerce-virtual-assistant'
  and l.slug = 'products-variants-skus-and-source-data';

update public.training_lessons l
set content = '[{"type":"heading","text":"A product page has to sell and operate correctly"},{"type":"paragraph","text":"Product listings support discovery and conversion, but they also need to tell the truth about what is being purchased. The VA should combine approved product data, clear copy, correct media, and channel requirements without inventing features or guarantees."},{"type":"heading","text":"Core listing components"},{"type":"list","items":["Product title","Short and long description where used","Approved price","Variant choices","Product images or video","Key attributes","Size, dimensions, compatibility, or material information where relevant","Shipping or availability information","Policy links","SEO fields where the platform supports them","Category, collection, or taxonomy placement"]},{"type":"heading","text":"Write from approved facts"},{"type":"steps","items":["Start with the product source data.","Identify the customer''s likely questions.","Organize the approved facts in a useful order.","Use plain language.","Avoid unsupported superlatives.","Check that the description matches the actual variant or model.","Get specialist review for regulated or technical claims when required."]},{"type":"callout","title":"Do not improve copy by inventing benefits","text":"If the approved source says a bottle holds 750 mL, you can make that fact easier to understand. You should not add ''keeps drinks cold for 24 hours'' unless that claim is supported and approved."},{"type":"heading","text":"Image QA"},{"type":"list","items":["Correct product","Correct variant","No supplier watermark unless approved","No accidental private information","Reasonable crop on desktop and mobile","Consistent order","Readable diagrams","No duplicate images","File size appropriate for the site","Alt text where required by the workflow"]},{"type":"heading","text":"SEO without stuffing"},{"type":"paragraph","text":"Use the product''s real name and relevant descriptive terms naturally. Avoid filling titles and descriptions with repeated keywords. Product SEO should support accurate discovery, not turn the listing into unreadable search-engine copy."},{"type":"scenario","title":"The supplier description makes a stronger claim","text":"The supplier sheet says a product is ''water resistant'', but an old marketplace listing says ''waterproof''. Do not copy the stronger wording because it sounds better. Use the current approved source and flag the conflicting old listing for correction."},{"type":"heading","text":"Pre-publish product QA"},{"type":"list","items":["Title matches product","Variant selection works","Prices are correct","Images match variants","Inventory setting is correct","Description uses approved facts","Links work","Policy information is accessible","Mobile layout is usable","Final status and visibility are correct"]},{"type":"heading","text":"Practice"},{"type":"paragraph","text":"Draft a fictional product QA sheet with at least 20 checks covering data, variants, images, copy, pricing, inventory, links, mobile display, and publication state."}]'::jsonb,
    estimated_minutes = 30,
    content_version = l.content_version + 1,
    reviewed_by = null,
    last_reviewed_at = null,
    is_published = false,
    updated_at = now()
from public.training_modules m
join public.training_courses c on c.id = m.course_id
where l.module_id = m.id
  and c.slug = 'ecommerce-virtual-assistant'
  and l.slug = 'product-listing-and-content-qa';

update public.training_lessons l
set content = '[{"type":"heading","text":"Bulk changes multiply both speed and risk"},{"type":"paragraph","text":"Bulk imports, exports, collection rules, mass price changes, tag changes, inventory updates, and marketplace feeds can save hours. They can also damage hundreds of listings in seconds. Treat bulk work as a controlled operation rather than routine data entry."},{"type":"heading","text":"Before a bulk change"},{"type":"steps","items":["Define exactly which records should change.","Define exactly which fields should change.","Export or preserve a before-state when the client process allows it.","Check whether automation or integrations depend on the affected fields.","Test on a small sample.","Confirm expected record count.","Get approval for high-impact changes.","Prepare a rollback method."]},{"type":"callout","title":"Do not use the entire catalog as your test set","text":"A bulk operation should be proven on a small controlled sample first. If the sample behaves unexpectedly, stop before scaling the change."},{"type":"heading","text":"Collections and merchandising"},{"type":"list","items":["Manual collection: products are intentionally added by someone.","Rule-based collection: products appear based on tags, type, price, inventory, or other conditions.","Featured placement: selected products are intentionally promoted.","Sort order: may be manual, automated, sales-based, newest-first, or platform-defined.","Availability rules: out-of-stock products may be hidden, shown, or moved according to store policy."]},{"type":"heading","text":"Common bulk-update mistakes"},{"type":"list","items":["Wrong delimiter or column mapping","Blank cells overwriting existing data","Text converted into numbers or dates incorrectly","SKUs losing leading zeroes","Prices imported into the wrong currency or field","Tags replaced instead of appended","HTML or formatting broken","Variants duplicated","Products accidentally published or archived"]},{"type":"scenario","title":"The sale-tag cleanup","text":"You are asked to remove an old promotion tag from 600 products. That tag also controls an automated collection. Do not delete it blindly. Identify every dependency, confirm the collection''s replacement logic, test a small set, and only then proceed with the approved cleanup."},{"type":"heading","text":"Post-change verification"},{"type":"steps","items":["Check record counts.","Spot-check several affected products.","Check one unaffected product.","Check collections and filters.","Check front-end visibility.","Check integration or feed status.","Record what changed and when."]},{"type":"heading","text":"Merchandising support without inventing strategy"},{"type":"paragraph","text":"A VA can implement approved product ordering, collections, launch groupings, bundles, or featured selections. Unless delegated, do not independently change commercial strategy, margin, discount depth, or product priority based on your own assumptions."},{"type":"heading","text":"Practice"},{"type":"paragraph","text":"Write a fictional bulk-update plan for 250 products that need a new collection tag and corrected vendor field. Include backup, test sample, expected counts, dependencies, rollback, and verification."}]'::jsonb,
    estimated_minutes = 30,
    content_version = l.content_version + 1,
    reviewed_by = null,
    last_reviewed_at = null,
    is_published = false,
    updated_at = now()
from public.training_modules m
join public.training_courses c on c.id = m.course_id
where l.module_id = m.id
  and c.slug = 'ecommerce-virtual-assistant'
  and l.slug = 'bulk-updates-collections-and-merchandising-support';

update public.training_lessons l
set content = '[{"type":"heading","text":"Orders move through states, not just ''open'' and ''done''"},{"type":"paragraph","text":"An order can be created, paid, partially paid, under review, unfulfilled, partially fulfilled, shipped, delivered, cancelled, refunded, returned, or disputed depending on the platform. Your job is to understand the client''s states and make exceptions visible instead of forcing every order through the happy path."},{"type":"heading","text":"Common order checks"},{"type":"list","items":["Payment status","Customer contact details","Shipping address","Product and variant","Inventory availability","Fulfilment location","Shipping method","Order notes","Fraud-review or risk flag if the platform provides one","Special instructions","Previous customer communication"]},{"type":"callout","title":"A risk flag is not permission to accuse the customer","text":"If the platform or payment provider marks an order for review, follow the client''s fraud-review workflow. Do not tell the customer they committed fraud, request sensitive documents outside approved procedures, or bypass the review just to ship faster."},{"type":"heading","text":"Exception categories"},{"type":"list","items":["Payment exception","Inventory exception","Address exception","Duplicate order","Customer change request","Cancellation request","Fraud/risk review","Fulfilment delay","Marketplace sync issue","Damaged or missing item"]},{"type":"heading","text":"Exception workflow"},{"type":"steps","items":["Record the issue.","Confirm the source information.","Identify the operational consequence.","Check the approved policy or workflow.","Take reversible approved action where possible.","Escalate decisions outside your authority.","Communicate confirmed status to the customer when required.","Track until resolved."]},{"type":"scenario","title":"Customer asks to change the address after fulfilment started","text":"Do not simply edit the address. Check fulfilment status, carrier or warehouse rules, fraud and payment implications, and the store''s address-change policy. If the shipment is already committed, explain the available approved options rather than promising a change."},{"type":"heading","text":"Order notes should preserve history"},{"type":"list","items":["What the customer requested","When they requested it","What action was taken","Who approved any exception","What was communicated","What remains unresolved","Next follow-up date"]},{"type":"heading","text":"Do not hide failed orders"},{"type":"paragraph","text":"Cancelled, refunded, disputed, and failed orders may matter to finance, inventory, fraud analysis, and customer support. Follow the store''s retention process rather than deleting inconvenient records."},{"type":"heading","text":"Practice"},{"type":"paragraph","text":"Create an exception matrix for eight fictional orders: payment review, out of stock, wrong address, duplicate order, cancellation request, delayed fulfilment, damaged item, and marketplace sync failure. Define the next action and escalation owner for each."}]'::jsonb,
    estimated_minutes = 30,
    content_version = l.content_version + 1,
    reviewed_by = null,
    last_reviewed_at = null,
    is_published = false,
    updated_at = now()
from public.training_modules m
join public.training_courses c on c.id = m.course_id
where l.module_id = m.id
  and c.slug = 'ecommerce-virtual-assistant'
  and l.slug = 'order-processing-and-exception-tracking';

update public.training_lessons l
set content = '[{"type":"heading","text":"Shipping updates should reflect confirmed logistics"},{"type":"paragraph","text":"Customers care about when an order will arrive, but the VA should not promise a date that the carrier or fulfilment provider has not confirmed. Good shipping communication explains the verified status, what the store is doing, and what happens next."},{"type":"heading","text":"Understand the fulfilment chain"},{"type":"steps","items":["Order is released for fulfilment.","Items are picked and packed.","A label or shipment record is created.","The carrier receives the parcel.","Tracking begins updating.","The parcel moves through the network.","Delivery is attempted or completed.","Exceptions are investigated when status stalls or fails."]},{"type":"callout","title":"Label created does not always mean carrier received","text":"A tracking number can exist before the parcel is physically scanned by the carrier. Use the actual carrier status and the store''s policy before telling a customer the package is already moving."},{"type":"heading","text":"Useful shipping status messages"},{"type":"list","items":["Order received","Preparing for fulfilment","Shipped with tracking","Carrier delay","Delivery attempted","Delivered","Investigation opened","Replacement/refund pending approval where relevant"]},{"type":"heading","text":"Investigating a delayed parcel"},{"type":"steps","items":["Confirm order and tracking number.","Check the carrier status.","Check fulfilment notes.","Check promised or estimated delivery window from the approved source.","Check whether an investigation threshold has been reached.","Open the required carrier/3PL case if authorized.","Record case number and next checkpoint.","Update the customer with confirmed information."]},{"type":"scenario","title":"Tracking says delivered, customer says not received","text":"Do not accuse the customer or immediately promise a refund. Follow the store''s delivered-not-received process: verify address, carrier status, delivery evidence where available, customer checks, investigation requirements, and escalation threshold."},{"type":"heading","text":"Cross-border caution"},{"type":"paragraph","text":"International deliveries can involve customs, duties, taxes, restricted items, local carrier handoffs, and longer tracking gaps. Use the client''s approved shipping information and carrier sources. Do not provide customs or tax advice unless the client has a defined approved response."},{"type":"heading","text":"Shipping communication QA"},{"type":"list","items":["Correct order","Correct tracking number","Correct carrier","No invented delivery promise","Clear next step","Investigation reference where relevant","Customer details kept private","Order record updated"]},{"type":"heading","text":"Practice"},{"type":"paragraph","text":"Write three fictional customer updates: carrier delay, delivery attempt, and delivered-not-received investigation. Each should state confirmed status, action taken, next step, and what the customer should expect."}]'::jsonb,
    estimated_minutes = 30,
    content_version = l.content_version + 1,
    reviewed_by = null,
    last_reviewed_at = null,
    is_published = false,
    updated_at = now()
from public.training_modules m
join public.training_courses c on c.id = m.course_id
where l.module_id = m.id
  and c.slug = 'ecommerce-virtual-assistant'
  and l.slug = 'shipping-tracking-and-fulfilment-communication';

update public.training_lessons l
set content = '[{"type":"heading","text":"Policy creates consistency"},{"type":"paragraph","text":"Returns and refunds affect customers, inventory, payments, accounting, fraud controls, and profitability. A VA should apply the store''s approved policy consistently and escalate exceptions instead of making emotional or improvised decisions."},{"type":"heading","text":"Start with the request"},{"type":"list","items":["Order number","Customer","Product and variant","Reason","Delivery date","Item condition if relevant","Photos or evidence where policy requires it","Requested outcome","Prior communication"]},{"type":"heading","text":"Check policy before promising the outcome"},{"type":"steps","items":["Confirm return window.","Confirm product eligibility.","Confirm condition requirements.","Check final-sale or excluded categories.","Check who pays return shipping if defined.","Check refund, exchange, store-credit, or replacement options.","Check approval limits.","Explain the approved process clearly."]},{"type":"callout","title":"Empathy does not mean inventing an exception","text":"You can acknowledge that a situation is frustrating while still following policy. If the customer asks for something outside your authority, document the facts and escalate rather than promising it."},{"type":"heading","text":"Refund-control basics"},{"type":"list","items":["Use the approved payment or commerce system.","Refund only the approved amount.","Confirm whether shipping, tax, discounts, or gift cards are handled automatically.","Avoid sending money through an alternate method outside process.","Record approval for exceptions.","Do not mark a refund complete until the system confirms it."]},{"type":"scenario","title":"Return outside the normal window","text":"A loyal customer asks for a refund five days outside policy and says another employee promised it. Do not approve or deny based on loyalty alone. Check the conversation history, confirm the policy, document the claimed promise, and escalate to the person authorized to make an exception."},{"type":"heading","text":"Exchanges and replacements"},{"type":"list","items":["Check replacement inventory.","Confirm the correct variant.","Check whether the original item must be returned.","Record shipping or return label details.","Do not create a duplicate charge unless process requires it.","Update the customer and order record."]},{"type":"heading","text":"Abuse and disputes"},{"type":"paragraph","text":"If behavior suggests repeated policy abuse, payment dispute, threatening conduct, or suspected fraud, follow the store''s escalation process. Do not accuse the customer, retaliate, or bypass normal evidence and review procedures."},{"type":"heading","text":"Practice"},{"type":"paragraph","text":"Handle five fictional cases: wrong size, damaged item, late return, missing parcel, and duplicate purchase. For each, state the information you need, policy check, action you can take, and escalation point."}]'::jsonb,
    estimated_minutes = 30,
    content_version = l.content_version + 1,
    reviewed_by = null,
    last_reviewed_at = null,
    is_published = false,
    updated_at = now()
from public.training_modules m
join public.training_courses c on c.id = m.course_id
where l.module_id = m.id
  and c.slug = 'ecommerce-virtual-assistant'
  and l.slug = 'returns-refunds-exchanges-and-policy-based-support';

update public.training_lessons l
set content = '[{"type":"heading","text":"One customer can contact the store in several places"},{"type":"paragraph","text":"A customer may email, start a chat, message a social account, reply through a marketplace, or submit a form about the same order. Strong support preserves context across channels so the customer does not have to restart the story each time."},{"type":"heading","text":"Common e-commerce questions"},{"type":"list","items":["Where is my order?","Can I change my address?","Can I cancel?","Which size or variant should I choose?","Is this item in stock?","How do I return it?","I received the wrong item.","The product arrived damaged.","My discount code did not work.","Why was I charged this amount?"]},{"type":"heading","text":"A useful support response"},{"type":"steps","items":["Acknowledge the actual issue.","Confirm relevant order facts.","State the verified status.","Explain the approved next action.","Set realistic expectations.","Record the interaction in the source system."]},{"type":"callout","title":"Avoid fake empathy and canned filler","text":"Customers usually need a clear answer more than a paragraph of scripted sympathy. Be polite, specific, and useful. Do not over-apologize or add generic phrases that make the response feel automated."},{"type":"heading","text":"Marketplace boundaries"},{"type":"list","items":["Follow each marketplace''s communication rules.","Keep required communication inside the marketplace when policy requires it.","Do not move customers off-platform to bypass fees or rules.","Use approved refund and dispute workflows.","Keep marketplace-specific promises separate from the direct store if policies differ."]},{"type":"scenario","title":"Same customer, two channels","text":"A customer emails about a delayed order and then sends a marketplace message an hour later. Check whether both messages refer to the same order, consolidate the context in the support record, and avoid sending contradictory updates from two channels."},{"type":"heading","text":"Escalation triggers"},{"type":"list","items":["Payment dispute","Threat or safety issue","Privacy request","Legal complaint","Repeated failed delivery","High-value exception","VIP or account-specific process","Suspected fraud","Public complaint gaining traction"]},{"type":"heading","text":"Support notes"},{"type":"list","items":["Customer request","Order","Verified status","Action taken","Policy applied","Exception requested","Escalation owner","Next follow-up"]},{"type":"heading","text":"Practice"},{"type":"paragraph","text":"Draft four fictional support responses for a delayed order, damaged item, failed discount code, and wrong variant. Keep each response specific, policy-based, and free of generic filler."}]'::jsonb,
    estimated_minutes = 30,
    content_version = l.content_version + 1,
    reviewed_by = null,
    last_reviewed_at = null,
    is_published = false,
    updated_at = now()
from public.training_modules m
join public.training_courses c on c.id = m.course_id
where l.module_id = m.id
  and c.slug = 'ecommerce-virtual-assistant'
  and l.slug = 'customer-service-across-email-chat-and-marketplaces';

update public.training_lessons l
set content = '[{"type":"heading","text":"Inventory data should help prevent surprises"},{"type":"paragraph","text":"A VA may monitor stock, supplier updates, low-stock alerts, incoming purchase orders, backorders, and inventory mismatches. The goal is not to invent demand forecasts or reorder quantities without authority. It is to make shortages and discrepancies visible early enough for the responsible person to act."},{"type":"heading","text":"Inventory terms to understand"},{"type":"list","items":["On hand: physically recorded stock.","Available: stock that can currently be sold after reservations or rules.","Committed: stock already allocated to orders.","Incoming: stock expected from supplier or transfer.","Backorder: demand accepted before stock is available if the store permits it.","Safety stock: buffer defined by the business.","Reorder point: trigger defined by the business.","Stock adjustment: manual change to recorded quantity."]},{"type":"callout","title":"Never change stock just to make the storefront look right","text":"If the system shows a mismatch, investigate the source. A manual quantity edit without evidence can create overselling, warehouse errors, and bad financial records."},{"type":"heading","text":"Low-stock monitoring"},{"type":"steps","items":["Use the client''s defined threshold.","Check current available stock.","Check open orders or committed units.","Check incoming stock.","Check supplier lead time where maintained.","Flag high-risk products.","Route reorder decisions to the authorized owner.","Record expected replenishment only when confirmed."]},{"type":"heading","text":"Common mismatch causes"},{"type":"list","items":["Unprocessed return","Damaged stock","Cancelled order not released","Marketplace sync delay","Warehouse count error","Duplicate SKU","Manual adjustment","Supplier short shipment","Bundle/component logic"]},{"type":"scenario","title":"Inventory says 12, warehouse says 8","text":"Do not average the numbers or silently change one system. Identify which records explain the difference, check open orders and adjustments, flag the four-unit discrepancy, and escalate for physical or system reconciliation."},{"type":"heading","text":"Supplier follow-up"},{"type":"list","items":["Purchase order or reference","Expected quantity","Expected date","Confirmed changes","Short shipment","Backordered items","Next follow-up","Owner for commercial negotiation"]},{"type":"heading","text":"Stockout communication"},{"type":"paragraph","text":"If stock is unavailable, use the client''s approved process for product visibility, backorders, substitutions, cancellations, or customer communication. Do not invent a restock date or substitute a product without authorization."},{"type":"heading","text":"Practice"},{"type":"paragraph","text":"Create a fictional low-stock report for ten SKUs. Include available, committed, incoming, expected replenishment, discrepancy flag, and the next action owner."}]'::jsonb,
    estimated_minutes = 30,
    content_version = l.content_version + 1,
    reviewed_by = null,
    last_reviewed_at = null,
    is_published = false,
    updated_at = now()
from public.training_modules m
join public.training_courses c on c.id = m.course_id
where l.module_id = m.id
  and c.slug = 'ecommerce-virtual-assistant'
  and l.slug = 'inventory-monitoring-and-reorder-administration';

update public.training_lessons l
set content = '[{"type":"heading","text":"Promotions combine marketing and store operations"},{"type":"paragraph","text":"A promotion can affect price, margin, eligibility, checkout, inventory, customer expectations, email, paid media, social, marketplaces, and support. An E-commerce VA should make the approved terms consistent across the entire customer journey."},{"type":"heading","text":"Promotion fields to confirm"},{"type":"list","items":["Offer","Discount amount or percentage","Eligible products or collections","Excluded products","Minimum spend","Customer eligibility","Code or automatic discount","Start date and time","End date and time","Time zone","Usage limits","Stacking rules","Required customer-facing terms"]},{"type":"heading","text":"Build the promotion safely"},{"type":"steps","items":["Use the approved offer brief.","Configure the promotion in the correct environment.","Test eligible items.","Test excluded items.","Test minimums or conditions.","Test mobile checkout.","Check tax/shipping interaction if relevant.","Check customer-facing copy.","Check scheduled start/end.","Record final approval."]},{"type":"callout","title":"A code that works is not enough","text":"The promotion also has to apply to the right products, the right customers, the right dates, and the right amount. Test the boundary conditions, not only one successful checkout."},{"type":"heading","text":"Launch dependencies"},{"type":"list","items":["Inventory available","Product pages correct","Discount configured","Landing/collection page live","Email correct","Social assets approved","Support briefed","Tracking ready","End-of-promotion rollback prepared"]},{"type":"scenario","title":"The code discounts excluded products","text":"During QA, a discount applies to a premium collection that the approved brief says is excluded. Stop launch of the affected promotion, correct the rule, test both eligible and excluded items, and only then clear it for use."},{"type":"heading","text":"During the promotion"},{"type":"list","items":["Watch code failures.","Watch unusual order exceptions.","Watch stockouts.","Route customer questions.","Track oversell risk.","Record any emergency rule change and approval."]},{"type":"heading","text":"After the promotion"},{"type":"steps","items":["Confirm the promotion ended.","Remove or archive outdated customer-facing copy.","Check any scheduled assets.","Record performance period.","Document issues.","Reconcile exceptions such as manual discounts or refunds."]},{"type":"heading","text":"Practice"},{"type":"paragraph","text":"Create a fictional promotion launch checklist for 20% off selected products for three days. Include eligibility, exclusions, time zone, QA cases, inventory checks, support briefing, launch monitoring, and shutdown steps."}]'::jsonb,
    estimated_minutes = 30,
    content_version = l.content_version + 1,
    reviewed_by = null,
    last_reviewed_at = null,
    is_published = false,
    updated_at = now()
from public.training_modules m
join public.training_courses c on c.id = m.course_id
where l.module_id = m.id
  and c.slug = 'ecommerce-virtual-assistant'
  and l.slug = 'promotions-discount-codes-and-launch-checklists';

update public.training_lessons l
set content = '[{"type":"heading","text":"Store reporting should show where operations need attention"},{"type":"paragraph","text":"A useful E-commerce VA report does more than list sales. It can show order exceptions, fulfilment delay, support volume, return reasons, inventory risk, promotion issues, and marketplace differences that require action."},{"type":"heading","text":"Operational reporting areas"},{"type":"list","items":["Orders received","Orders awaiting fulfilment","Orders in exception","Shipping delays","Returns/refunds","Support backlog","Low-stock items","Inventory mismatches","Promotion issues","Marketplace feed or listing errors"]},{"type":"heading","text":"Separate activity from outcome"},{"type":"list","items":["Activity: 42 support tickets answered. Outcome: 7 refunds, 4 shipping investigations, 2 product-data fixes.","Activity: 60 products updated. Outcome: 58 verified, 2 held for source-data conflict.","Activity: 12 delayed orders reviewed. Outcome: 8 carrier delays, 3 fulfilment delays, 1 address exception."]},{"type":"callout","title":"A sales number without context can hide operational damage","text":"Revenue may rise during a promotion while refunds, stockouts, support backlog, or fulfilment delay also rise. Report the operational picture needed for decisions, not only the most flattering number."},{"type":"heading","text":"Marketplace handoff differences"},{"type":"paragraph","text":"Different marketplaces may use different listing rules, fulfilment methods, message systems, return policies, dispute procedures, and performance metrics. Keep marketplace-specific requirements explicit instead of assuming the direct store workflow applies everywhere."},{"type":"steps","items":["Identify the marketplace.","Record the issue or task.","Link the listing/order/message.","State the marketplace-specific rule or status if known from approved documentation.","Identify what can be handled by the VA.","Escalate restricted or commercial decisions.","Record the resolution."]},{"type":"scenario","title":"Direct store and marketplace disagree","text":"The direct store shows a product available while a marketplace feed marks it out of stock. Do not force the marketplace quantity to match without checking the sync source. Identify the inventory owner, feed status, SKU mapping, and last sync before changing data."},{"type":"heading","text":"Daily handoff structure"},{"type":"list","items":["Completed outcomes","Open order exceptions","Customer issues requiring decision","Inventory risks","Marketplace issues","Promotion or pricing exceptions","Tomorrow''s first actions"]},{"type":"heading","text":"Reporting integrity"},{"type":"list","items":["Use consistent date range and time zone.","Define order and refund states.","Avoid double-counting marketplace and store records.","Flag missing data.","Keep cancelled/refunded orders visible where the report definition requires them.","Do not state a cause unless evidence supports it."]},{"type":"heading","text":"Practice"},{"type":"paragraph","text":"Prepare a fictional daily store report with sales context, five order exceptions, three support issues, two low-stock alerts, one marketplace sync problem, and a concise decision list for the store manager."}]'::jsonb,
    estimated_minutes = 30,
    content_version = l.content_version + 1,
    reviewed_by = null,
    last_reviewed_at = null,
    is_published = false,
    updated_at = now()
from public.training_modules m
join public.training_courses c on c.id = m.course_id
where l.module_id = m.id
  and c.slug = 'ecommerce-virtual-assistant'
  and l.slug = 'store-reporting-and-marketplace-handoffs';

update public.training_lessons l
set content = '[{"type":"heading","text":"Final practice: run an e-commerce operations day"},{"type":"paragraph","text":"This simulation combines product data, orders, fulfilment, shipping, returns, customer support, inventory, promotions, marketplaces, and reporting. All products, customers, orders, and businesses are fictional."},{"type":"heading","text":"Scenario background"},{"type":"paragraph","text":"You support a growing online retailer that sells through its own store and one marketplace. The business uses a commerce platform, warehouse partner, help desk, email tool, and inventory sync. You may process routine tasks and policy-based support, but you cannot invent pricing, approve out-of-policy refunds, override fraud review, or make purchasing decisions."},{"type":"heading","text":"Incoming work"},{"type":"list","items":["A new product has two variants sharing the same SKU.","A paid order contains an item that the warehouse shows as out of stock.","A customer asks to change their shipping address after fulfilment has started.","A tracking page says delivered, but the customer says the parcel never arrived.","A customer requests a refund outside the normal return window and says a previous agent promised an exception.","The CRM contains two support conversations about the same order from different channels.","Inventory says 12 units are available while the warehouse count says 8.","Tomorrow''s promotion incorrectly discounts an excluded premium collection.","The marketplace listing shows out of stock while the direct store shows inventory available.","The store manager asks for an end-of-day operational summary."]},{"type":"heading","text":"Part 1: Prioritise"},{"type":"steps","items":["Rank the ten issues by customer impact and operational risk.","Identify which issues could cause overselling, payment, or fulfilment problems.","Identify which actions you can take independently.","Identify which require policy, fraud, finance, warehouse, purchasing, or manager approval.","Identify which issues should block a promotion or product update."]},{"type":"heading","text":"Part 2: Produce the work"},{"type":"list","items":["Write the duplicate-SKU correction note.","Create the out-of-stock order exception.","Write the safe response to the address-change request.","Create the delivered-not-received investigation record.","Write the outside-policy refund escalation.","Consolidate the two-channel support context.","Create the inventory discrepancy report.","Document the promotion QA failure and stop-launch action.","Create the marketplace inventory-sync handoff.","Prepare the end-of-day store summary."]},{"type":"callout","title":"Assessment standard","text":"You are assessed on factual accuracy, policy discipline, product-data quality, order judgment, customer communication, inventory integrity, promotion QA, marketplace handoffs, and whether you avoid promises or decisions outside your authority."},{"type":"heading","text":"Part 3: Self-review"},{"type":"list","items":["Did you avoid changing stock without evidence?","Did you avoid promising an address change after fulfilment started?","Did you follow investigation rather than accusation for the missing parcel?","Did you escalate the refund exception?","Did you stop the broken promotion before launch?","Did you check the source of the marketplace inventory mismatch?","Did every unresolved issue have an owner and next action?"]},{"type":"heading","text":"What excellent work looks like"},{"type":"paragraph","text":"Excellent E-commerce VA work keeps the store truthful and operationally stable. Product information matches the source, orders move through the correct process, exceptions stay visible, customers receive verified updates, inventory is not manipulated to hide problems, promotions are tested before launch, and handoffs make the next action obvious."},{"type":"scenario","title":"Optional stretch scenario","text":"At the end of your shift, a high-value customer places a large order that the platform marks for review and the manager is offline. Explain what reversible actions you would take, what you would not do, what information you would preserve, and how you would hand the decision to the authorized person."}]'::jsonb,
    estimated_minutes = 30,
    content_version = l.content_version + 1,
    reviewed_by = null,
    last_reviewed_at = null,
    is_published = false,
    updated_at = now()
from public.training_modules m
join public.training_courses c on c.id = m.course_id
where l.module_id = m.id
  and c.slug = 'ecommerce-virtual-assistant'
  and l.slug = 'composite-e-commerce-va-work-simulation';

update public.training_assessments
set instructions = 'Complete the composite E-commerce VA work simulation from the final lesson and submit: (1) a prioritized operations queue, (2) a duplicate-SKU correction note, (3) an out-of-stock order exception, (4) a policy-safe address-change response, (5) a delivered-not-received investigation record, (6) an out-of-policy refund escalation, (7) a consolidated multi-channel support note, (8) an inventory discrepancy report, (9) a promotion QA stop-launch note, (10) a marketplace inventory-sync handoff, and (11) an end-of-day store summary. Review should assess product-data accuracy, policy discipline, fulfilment judgment, customer communication, inventory integrity, promotion QA, marketplace handoffs, and escalation judgment. The learner must not invent stock, override fraud review, approve unauthorized refunds, or make unsupported delivery or pricing promises.',
    assessment_type = 'practical',
    pass_score = null,
    is_published = false,
    updated_at = now()
where course_id = (select id from public.training_courses where slug='ecommerce-virtual-assistant');
